let font;
const DONTTOUCHDIST = 50;
const str = "Don´t Touch";
let pts;
let startHSBValue, scaleHValues;

function preload() {
  font = loadFont('https://openprocessing.org/sketch/1945181/files/Geologica.ttf');
}

function setup() {
  createCanvas(innerWidth, innerHeight);
	pixelDensity(1);
	colorMode(HSB, 100);
	startHSBValue = floor(random(100));
	scaleHValues = random(0.1, 2);
  stroke(0);
  fill(255, 104, 204);

	textAlign(LEFT, CENTER)

  let points = font.textToPoints(str, 0, 0, 20, {
    sampleFactor: 3,
    simplifyThreshold: 0
  });
  let bounds = font.textBounds(str, 0, 0, 20);

	const sclX = width / bounds.w;
	const sclY = height / bounds.h;
	let scl = min(sclX, sclY) * 0.8;

	pts = [];
	for (let p of points) {
		const x = (p.x - bounds.x + bounds.w * 0.1) * scl
		const offY = (height - bounds.h * scl) * 0.5;
		const y = (p.y + bounds.h) * scl + offY;
		pts.push(new Particle(x, y));
	}
}

function windowResized() {
	setup();
}
function mousePressed() {
	if (mouseButton === LEFT)	{
		startHSBValue = floor(random(100));
		scaleHValues = random(0.1, 2.5);
	}
}


function draw() {
  // background(255);
	background((startHSBValue) % 100 , 15, 85);

  // translate(-bounds.x * width / bounds.w, -bounds.y * height / bounds.h);
	// for (let p of pts) {
	for (let i = 0; i < pts.length; i++) {
		let p = pts[i];
    p.update(DONTTOUCHDIST + random(-DONTTOUCHDIST*0.2, DONTTOUCHDIST*0.2));
    p.show();
  }

	const rotor = 9
	translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	rotate(frameCount * 0.1)
	stroke(0, 15, 15, 25)
	for (let i = 0; i < rotor; i++) {
		line(-DONTTOUCHDIST, 0, DONTTOUCHDIST, 0);
		rotate(TWO_PI/rotor)
	}
}

// Simple Particle class
class Particle {
	constructor(x, y) {
		// initial position
		this.ix = x;
		this.iy = y;
		// current position
		this.cx = x;
		this.cy = y;
	}

	update(len, debug = false) {
		let d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.cx, this.cy)
		// if to near expand position from mouse
		if (d < len) {
			let deltaVec = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.cx, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.cy);
			deltaVec.normalize().mult(d-len);
			this.cx += deltaVec.x
			this.cy += deltaVec.y
		}

		// steering to initial position
		this.cx = lerp(this.ix, this.cx, 0.95);
		this.cy = lerp(this.iy, this.cy, 0.95);
	}

	show() {
		push()
		noStroke();
		let n = noise(frameCount * 0.025);
		// let h = ((this.ix + this.iy) * (scaleHValues + n *0.5) % 25 + startHSBValue) % 100;
		let h = ((this.ix + this.iy) * (scaleHValues) % 25 + startHSBValue) % 100; // (scaleHValues * (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))
		h += n * 20 - 10; // color deviation over time
		let c = color(h, 75, 75)
		fill(lerpColor(c, color(0, 100, 100), dist(this.ix, this.iy, this.cx, this.cy)/DONTTOUCHDIST));
		var d = 2 + noise(this.cx, this.cy) * 8;
		circle(this.cx, this.cy, d);
		pop();
	}
}
